        {"class",          t_check,    .dflt.check = "AIS"}, \
        {"type",           t_uinteger, .addr.uinteger = &ais->type}, \
        {"device",         t_string,   .addr.string = path, \
                                          .len = pathlen}, \
        {"repeat",         t_uinteger, .addr.uinteger = &ais->repeat}, \
        {"scaled",         t_boolean,  .addr.boolean = &scaled, \
                                          .dflt.boolean = false}, \
